import type { AudioPlayer } from 'expo-audio';

import type { Rarity } from '../data/rarity';
import { REVEAL_FX } from '../logic/revealFx';

/**
 * Short UI sounds (the pack-reveal chimes). Like `haptics.ts`: one switch kept
 * outside React (the player's setting), every call fire-and-forget, and any
 * failure is silent. A missing sound must never break the pack opening.
 *
 * The chimes are generated by scripts/audio/make-chimes.py.
 */

const SOURCES: Record<Rarity, number> = {
  common: require('../../assets/sounds/reveal-common.wav'),
  uncommon: require('../../assets/sounds/reveal-uncommon.wav'),
  rare: require('../../assets/sounds/reveal-rare.wav'),
  epic: require('../../assets/sounds/reveal-epic.wav'),
  legendary: require('../../assets/sounds/reveal-legendary.wav'),
};

let enabled = true;
let players: Partial<Record<Rarity, AudioPlayer>> = {};
let modeSet = false;

type ExpoAudio = typeof import('expo-audio');
let audioModule: ExpoAudio | null | undefined;

/**
 * Loaded on first use, not at import: expo-audio touches its native module as
 * soon as it's imported, which would make every importer of the store (tests
 * included) depend on it. If it can't load, the game simply has no sound.
 */
function audio(): ExpoAudio | null {
  if (audioModule === undefined) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports -- lazy on purpose (see above)
      audioModule = require('expo-audio') as ExpoAudio;
    } catch {
      audioModule = null;
    }
  }
  return audioModule;
}

/** Mirrors the player's setting. */
export function setSoundEnabled(value: boolean) {
  enabled = value;
}

function player(rarity: Rarity): AudioPlayer | null {
  const a = audio();
  if (!a) return null;
  try {
    players[rarity] ??= a.createAudioPlayer(SOURCES[rarity]);
    return players[rarity] ?? null;
  } catch {
    return null;
  }
}

export const sound = {
  /**
   * Loads the chimes so the first reveal plays without a delay, and sets the
   * audio mode once: mix with the player's music, respect the iOS silent switch.
   */
  preload: () => {
    const a = audio();
    if (!a) return;
    if (!modeSet) {
      modeSet = true;
      a.setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
    }
    for (const r of Object.keys(SOURCES) as Rarity[]) player(r);
  },

  /** The rarity's reveal chime, from the start. */
  reveal: (rarity: Rarity) => {
    if (!enabled) return;
    const p = player(rarity);
    if (!p) return;
    try {
      p.volume = REVEAL_FX[rarity].volume;
      // Restart if it's still ringing from the previous card of the same rarity.
      p.seekTo(0).catch(() => {});
      p.play();
    } catch {
      // A sound is a bonus: never let it break the reveal.
    }
  },

  /** Frees the players (e.g. after the pack screen closes). */
  release: () => {
    for (const p of Object.values(players)) {
      try {
        p?.remove();
      } catch {
        // already gone
      }
    }
    players = {};
  },
};
